387: #ifdef Q_OS_WIN
388: #if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
389: int ElaAppBar::takeOverNativeEvent(const QByteArray& eventType, void* message, qintptr* result)
390: #else
391: int ElaAppBar::takeOverNativeEvent(const QByteArray& eventType, void* message, long* result)
392: #endif
393: {
394:     Q_D(ElaAppBar);
395:     if ((eventType != "windows_generic_MSG") || !message)
396:     {
397:         return 0;
398:     }
399:     const auto msg = static_cast<const MSG*>(message);
400:     const HWND hwnd = msg->hwnd;
401:     if (!hwnd || !msg)
402:     {
403:         return 0;
404:     }
405:     d->_currentWinID = (qint64)hwnd;
406:     const UINT uMsg = msg->message;
407:     const WPARAM wParam = msg->wParam;
408:     const LPARAM lParam = msg->lParam;
409:     switch (uMsg)
410:     {
411:     case WM_WINDOWPOSCHANGING:
412:     {
413:         WINDOWPOS* wp = reinterpret_cast<WINDOWPOS*>(lParam);
414:         if (wp != nullptr && (wp->flags & SWP_NOSIZE) == 0)
415:         {
416:             wp->flags |= SWP_NOCOPYBITS;
417:             *result = ::DefWindowProcW(hwnd, uMsg, wParam, lParam);
418:             return 1;
419:         }
420:         return 0;
421:     }
422:     case WM_NCPAINT:
423:     {
424:         if (!eWinHelper->getIsCompositionEnabled())
425:         {
426:             *result = FALSE;
427:             return 1;
428:         }
429:         else
430:         {
431:             return -1;
432:         }
433:     }
434:     case WM_NCACTIVATE:
435:     {
436:         if (eWinHelper->getIsCompositionEnabled())
437:         {
438:             *result = ::DefWindowProcW(hwnd, WM_NCACTIVATE, wParam, -1);
439:         }
440:         else
441:         {
442:             *result = TRUE;
443:         }
444:         return 1;
445:     }
446:     case WM_SIZE:
447:     {
448:         if (wParam == SIZE_RESTORED)
449:         {
450:             d->_changeMaxButtonAwesome(false);
451:         }
452:         else if (wParam == SIZE_MAXIMIZED)
453:         {
454:             d->_changeMaxButtonAwesome(true);
455:         }
456:         return 0;
457:     }
458: #if QT_VERSION <= QT_VERSION_CHECK(6, 0, 0)
459:     case WM_SHOWWINDOW:
460:     {
461:         if (wParam == FALSE)
462:         {
463:             return 0;
464:         }
465:         RECT windowRect{};
466:         ::GetWindowRect(hwnd, &windowRect);
467:         int windowWidth = windowRect.right - windowRect.left;
468:         int windowHeight = windowRect.bottom - windowRect.top;
469:         static UINT swpFlags = SWP_NOMOVE | SWP_NOZORDER | SWP_NOOWNERZORDER | SWP_FRAMECHANGED | SWP_NOACTIVATE;
470:         ::SetWindowPos(hwnd, nullptr, 0, 0, windowWidth + 1, windowHeight, swpFlags);
471:         ::SetWindowPos(hwnd, nullptr, 0, 0, windowWidth, windowHeight, swpFlags);
472:         return -1;
473:     }
474: #endif
475:     case WM_NCCALCSIZE:
476:     {
477:         if (wParam == FALSE)
478:         {
479:             return 0;
480:         }
481: #if (QT_VERSION >= QT_VERSION_CHECK(6, 5, 3) && QT_VERSION <= QT_VERSION_CHECK(6, 6, 1))
482:         if (::IsZoomed(hwnd))
483:         {
484:             this->move(7, 7);
485:             window()->setContentsMargins(8, 8 + height(), 8, 8);
486:         }
487:         else
488:         {
489:             this->move(0, 0);
490:             window()->setContentsMargins(0, height(), 0, 0);
491:         }
492:         *result = 0;
493:         return 1;
494: #else
495:         RECT* clientRect = &((NCCALCSIZE_PARAMS*)(lParam))->rgrc[0];
496:         if (eWinHelper->getIsWinVersionGreater10())
497:         {
498:             const LONG originTop = clientRect->top;
499:             const LRESULT hitTestResult = ::DefWindowProcW(hwnd, WM_NCCALCSIZE, wParam, lParam);
500:             if ((hitTestResult != HTERROR) && (hitTestResult != HTNOWHERE))
501:             {
502:                 *result = static_cast<long>(hitTestResult);
503:                 return 1;
504:             }
505:             clientRect->top = originTop;
506:         }
507:         if (::IsZoomed(hwnd))
508:         {
509: #if QT_VERSION >= QT_VERSION_CHECK(5, 14, 0)
510:             auto geometry = window()->screen()->geometry();
511: #else
512:             QScreen* screen = qApp->screenAt(window()->geometry().center());
513:             QRect geometry;
514:             if (!screen)
515:             {
516:                 screen = qApp->screenAt(QCursor::pos());
517:             }
518:             geometry = screen->geometry();
519: #endif
520:             clientRect->top = geometry.top();
521:             if (!eWinHelper->getIsWinVersionGreater10())
522:             {
523:                 quint32 borderThickness = eWinHelper->getResizeBorderThickness(hwnd);
524:                 clientRect->left = geometry.left();
525:                 clientRect->bottom -= borderThickness;
526:                 clientRect->right -= borderThickness;
527:             }
528:         }
529:         *result = WVR_REDRAW;
530:         return 1;
531: #endif
532:     }
533:     case WM_MOVE:
534:     {
535:         QScreen* currentScreen = qApp->screenAt(window()->geometry().center());
536:         if (currentScreen && currentScreen != d->_lastScreen)
537:         {
538:             if (d->_lastScreen)
539:             {
540:                 ::SetWindowPos(hwnd, nullptr, 0, 0, 0, 0, SWP_NOZORDER | SWP_NOOWNERZORDER | SWP_NOMOVE | SWP_NOSIZE | SWP_FRAMECHANGED);
541:                 ::RedrawWindow(hwnd, nullptr, nullptr, RDW_INVALIDATE | RDW_UPDATENOW);
542:             }
543:             d->_lastScreen = currentScreen;
544:         }
545:         break;
546:     }
547:     case WM_NCHITTEST:
548:     {
549:         if (d->_containsCursorToItem(d->_maxButton))
550:         {
551:             if (*result == HTNOWHERE)
552:             {
553:                 if (!d->_isHoverMaxButton)
554:                 {
555:                     d->_isHoverMaxButton = true;
556:                     d->_maxButton->setIsSelected(true);
557:                     d->_maxButton->update();
558:                 }
559:                 *result = HTZOOM;
560:             }
561:             return 1;
562:         }
563:         else
564:         {
565:             if (d->_isHoverMaxButton)
566:             {
567:                 d->_isHoverMaxButton = false;
568:                 d->_maxButton->setIsSelected(false);
569:                 d->_maxButton->update();
570:             }
571:         }
572:         POINT nativeLocalPos{GET_X_LPARAM(lParam), GET_Y_LPARAM(lParam)};
573:         ::ScreenToClient(hwnd, &nativeLocalPos);
574:         RECT clientRect{0, 0, 0, 0};
575:         ::GetClientRect(hwnd, &clientRect);
576:         auto clientWidth = clientRect.right - clientRect.left;
577:         auto clientHeight = clientRect.bottom - clientRect.top;
578:         bool left = nativeLocalPos.x < d->_win7Margins;
579:         bool right = nativeLocalPos.x > clientWidth - d->_win7Margins;
580:         bool top = nativeLocalPos.y < d->_margins;
581:         bool bottom = nativeLocalPos.y > clientHeight - d->_win7Margins;
582:         *result = HTNOWHERE;
583:         if (!d->_pIsOnlyAllowMinAndClose && !d->_pIsFixedSize && !window()->isFullScreen() && !window()->isMaximized())
584:         {
585:             if (left && top)
586:             {
587:                 *result = HTTOPLEFT;
588:             }
589:             else if (left && bottom)
590:             {
591:                 *result = HTBOTTOMLEFT;
592:             }
593:             else if (right && top)
594:             {
595:                 *result = HTTOPRIGHT;
596:             }
597:             else if (right && bottom)
598:             {
599:                 *result = HTBOTTOMRIGHT;
600:             }
601:             else if (left)
602:             {
603:                 *result = HTLEFT;
604:             }
605:             else if (right)
606:             {
607:                 *result = HTRIGHT;
608:             }
609:             else if (top)
610:             {
611:                 *result = HTTOP;
612:             }
613:             else if (bottom)
614:             {
615:                 *result = HTBOTTOM;
616:             }
617:         }
618:         if (0 != *result)
619:         {
620:             return 1;
621:         }
622:         if (d->_containsCursorToItem(this) && !window()->isFullScreen())
623:         {
624:             *result = HTCAPTION;
625:             return 1;
626:         }
627:         *result = HTCLIENT;
628:         return 1;
629:     }
630:     case WM_GETMINMAXINFO:
631:     {
632:         MINMAXINFO* minmaxInfo = reinterpret_cast<MINMAXINFO*>(lParam);
633:         RECT rect;
634:         SystemParametersInfo(SPI_GETWORKAREA, 0, &rect, 0);
635:         d->_lastMinTrackWidth = d->_calculateMinimumWidth();
636:         minmaxInfo->ptMinTrackSize.x = d->_lastMinTrackWidth * qApp->devicePixelRatio();
637:         minmaxInfo->ptMinTrackSize.y = parentWidget()->minimumHeight() * qApp->devicePixelRatio();
638:         minmaxInfo->ptMaxPosition.x = rect.left;
639:         minmaxInfo->ptMaxPosition.y = rect.top;
640:         return 1;
641:     }
642:     case WM_LBUTTONDBLCLK:
643:     {
644:         QVariantMap postData;
645:         postData.insert("WMClickType", ElaAppBarType::WMLBUTTONDBLCLK);
646:         ElaEventBus::getInstance()->post("WMWindowClicked", postData);
647:         return 0;
648:     }
649:     case WM_LBUTTONDOWN:
650:     {
651:         QVariantMap postData;
652:         postData.insert("WMClickType", ElaAppBarType::WMLBUTTONDOWN);
653:         ElaEventBus::getInstance()->post("WMWindowClicked", postData);
654:         return 0;
655:     }
656:     case WM_LBUTTONUP:
657:     {
658:         QVariantMap postData;
659:         postData.insert("WMClickType", ElaAppBarType::WMLBUTTONUP);
660:         ElaEventBus::getInstance()->post("WMWindowClicked", postData);
661:         return 0;
662:     }
663:     case WM_NCLBUTTONDOWN:
664:     {
665:         QVariantMap postData;
666:         postData.insert("WMClickType", ElaAppBarType::WMNCLBUTTONDOWN);
667:         ElaEventBus::getInstance()->post("WMWindowClicked", postData);
668:         if (d->_containsCursorToItem(d->_maxButton) || d->_pIsOnlyAllowMinAndClose)
669:         {
670:             return 1;
671:         }
672:         break;
673:     }
674:     case WM_NCLBUTTONUP:
675:     {
676:         QVariantMap postData;
677:         postData.insert("WMClickType", ElaAppBarType::WMNCLBUTTONDOWN);
678:         ElaEventBus::getInstance()->post("WMWindowClicked", postData);
679:         if (d->_containsCursorToItem(d->_maxButton) && !d->_pIsOnlyAllowMinAndClose)
680:         {
681:             d->onMaxButtonClicked();
682:             return 1;
683:         }
684:         break;
685:     }
686:     case WM_NCLBUTTONDBLCLK:
687:     {
688:         if (!d->_pIsOnlyAllowMinAndClose && !d->_pIsFixedSize)
689:         {
690:             return 0;
691:         }
692:         return 1;
693:     }
694:     case WM_NCRBUTTONDOWN:
695:     {
696:         if (wParam == HTCAPTION && !d->_pIsOnlyAllowMinAndClose)
697:         {
698:             d->_showAppBarMenu(QCursor::pos());
699:         }
700:         break;
701:     }
702:     case WM_KEYDOWN:
703:     case WM_SYSKEYDOWN:
704:     {
705:         if ((GetAsyncKeyState(VK_MENU) & 0x8000) && (GetAsyncKeyState(VK_SPACE) & 0x8000) && !d->_pIsOnlyAllowMinAndClose)
706:         {
707:             auto pos = window()->geometry().topLeft();
708:             d->_showAppBarMenu(QPoint(pos.x(), pos.y() + this->height()));
709:         }
710:         break;
711:     }
712:     }
713:     return -1;
714: }
715: #endif
