        if (::IsZoomed(hwnd))
        {
#if QT_VERSION >= QT_VERSION_CHECK(5, 14, 0)
            auto geometry = window()->screen()->geometry();
#else
            QScreen* screen = qApp->screenAt(window()->geometry().center());
            QRect geometry;
            if (!screen)
            {
                screen = qApp->screenAt(QCursor::pos());
